    /// Ticks the running sessions (W3C SCXML 6.4): what a child sent before is taken
    /// first, then the child takes its turn, then what it sent in it.
    public func tickChildren(engine: Engine<StaticInvokeOptionalPolicy>) {
        if !sceInvokeDoneGiven, let child = sceInvokeChildGiven {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "given",
                engine: engine
            )
            child.tick()
            sceSettleInvokeGiven(engine: engine)
        }
        if !sceInvokeDoneLifted, let child = sceInvokeChildLifted {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "lifted",
                engine: engine
            )
            child.tick()
            sceSettleInvokeLifted(engine: engine)
        }
        if !sceInvokeDoneAbsent, let child = sceInvokeChildAbsent {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "absent",
                engine: engine
            )
            child.tick()
            sceSettleInvokeAbsent(engine: engine)
        }
        if !sceInvokeDoneReplaced, let child = sceInvokeChildReplaced {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "replaced",
                engine: engine
            )
            child.tick()
            sceSettleInvokeReplaced(engine: engine)
        }
        if !sceInvokeDoneOver, let child = sceInvokeChildOver {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "over",
                engine: engine
            )
            child.tick()
            sceSettleInvokeOver(engine: engine)
        }
        if !sceInvokeDoneFits, let child = sceInvokeChildFits {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "fits",
                engine: engine
            )
            child.tick()
            sceSettleInvokeFits(engine: engine)
        }
    }

    /// Settles what every running child sent this machine while a delivery drove it
    /// (docs/adr/0045): one body for every drive of a child, so a save at any boundary
    /// of this session finds its buffer empty.
    public func settleChildren(engine: Engine<StaticInvokeOptionalPolicy>) {
        sceSettleInvokeGiven(engine: engine)
        sceSettleInvokeLifted(engine: engine)
        sceSettleInvokeAbsent(engine: engine)
        sceSettleInvokeReplaced(engine: engine)
        sceSettleInvokeOver(engine: engine)
        sceSettleInvokeFits(engine: engine)
    }

    /// The nearest deadline of a running child (W3C SCXML 6.4), so a host that walks
    /// time by `timeUntilNextScheduled` does not step over a timer a child armed. A
    /// child that has ended is skipped: the policy keeps it until its state exits, and
    /// what it armed is no longer owed.
    public func nextChildDeadline() -> Duration? {
        var soonest: Duration?
        if !sceInvokeDoneGiven, let due = sceInvokeChildGiven?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneLifted, let due = sceInvokeChildLifted?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneAbsent, let due = sceInvokeChildAbsent?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneReplaced, let due = sceInvokeChildReplaced?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneOver, let due = sceInvokeChildOver?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneFits, let due = sceInvokeChildFits?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        return soonest
    }

    /// Delivers a delayed `<send target="#_<invokeid>">` whose wait is over, by name:
    /// a child need not declare every event its parent sends (W3C SCXML 6.2 + 6.4).
    /// Whether the invocation was there to take it: one whose session has reached its
    /// final state has ended, and the engine reports the send it could not deliver
    /// (W3C SCXML C.1).
    public func deliverToInvocation(invokeID: String, eventName: String, eventData: String, sendID: String) -> Bool {
        if invokeID.utf8.elementsEqual("given".utf8) {
            if let child = sceInvokeChildGiven, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("lifted".utf8) {
            if let child = sceInvokeChildLifted, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("absent".utf8) {
            if let child = sceInvokeChildAbsent, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("replaced".utf8) {
            if let child = sceInvokeChildReplaced, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("over".utf8) {
            if let child = sceInvokeChildOver, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("fits".utf8) {
            if let child = sceInvokeChildFits, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("given".utf8) {
            return sceInvokeChildGiven.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("lifted".utf8) {
            return sceInvokeChildLifted.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("absent".utf8) {
            return sceInvokeChildAbsent.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("replaced".utf8) {
            return sceInvokeChildReplaced.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("over".utf8) {
            return sceInvokeChildOver.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("fits".utf8) {
            return sceInvokeChildFits.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["given"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildGiven.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["lifted"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildLifted.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["absent"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildAbsent.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["replaced"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildReplaced.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["over"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildOver.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["fits"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildFits.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["given"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildGiven {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["lifted"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildLifted {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["absent"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildAbsent {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["replaced"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildReplaced {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["over"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildOver {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["fits"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildFits {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
