        switch state {
        case .running:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsGiven += 1
                let generatedInvokeID = "running.\(sceInvokeStartsGiven).given"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .running,
                    documentID: "given"
