            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsLifted += 1
                let generatedInvokeID = "running.\(sceInvokeStartsLifted).lifted"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .running,
                    documentID: "lifted"
                ))
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsAbsent += 1
                let generatedInvokeID = "running.\(sceInvokeStartsAbsent).absent"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .running,
                    documentID: "absent"
                ))
            }
