    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticInvokeOptionalState, engine: Engine<StaticInvokeOptionalPolicy>, configurationBeforeExit: [StaticInvokeOptionalState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .running:
            cancelInvokesForState(&pendingInvokes, .running)
            sceInvokeChildGiven?.stop()
            sceInvokeChildGiven = nil
            activeInvokes["given"] = nil
            sceInvokeDoneGiven = false
            sceInvokeChildLifted?.stop()
            sceInvokeChildLifted = nil
            activeInvokes["lifted"] = nil
            sceInvokeDoneLifted = false
            sceInvokeChildAbsent?.stop()
            sceInvokeChildAbsent = nil
            activeInvokes["absent"] = nil
            sceInvokeDoneAbsent = false
            sceInvokeChildReplaced?.stop()
            sceInvokeChildReplaced = nil
            activeInvokes["replaced"] = nil
            sceInvokeDoneReplaced = false
            sceInvokeChildOver?.stop()
            sceInvokeChildOver = nil
            activeInvokes["over"] = nil
            sceInvokeDoneOver = false
            sceInvokeChildFits?.stop()
            sceInvokeChildFits = nil
            activeInvokes["fits"] = nil
            sceInvokeDoneFits = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
