    public func firstEnabledTransition(
        _ state: StaticInvokeOptionalState,
        event: StaticInvokeOptionalEvent,
        engine: Engine<StaticInvokeOptionalPolicy>
    ) -> EnabledTransition<StaticInvokeOptionalState>? {
        switch state {
        case .running:
            if event == .doneInvokeGiven {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeLifted {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeAbsent {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeReplaced {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 3,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeOver {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 4,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeFits {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 5,
